import java.util.*;

public class Main {
    public static void main(String[] args) {
        LiveTranscodePipeline pipeline = new LiveTranscodePipeline(4000); // 4 second latency budget

        // Segment 1: captured at t=1000, finishes transcoding at t=3500 (2500ms latency): within budget.
        System.out.println("Segment 1: " + pipeline.processSegment("seg-1", 1000, 3500));

        // Segment 2: captured at t=1000, finishes transcoding at t=6000 (5000ms latency): exceeds budget.
        System.out.println("Segment 2: " + pipeline.processSegment("seg-2", 1000, 6000));

        // Adaptive bitrate selection.
        Map<String, Integer> qualities = new LinkedHashMap<>();
        qualities.put("1080p", 6000);
        qualities.put("720p", 3000);
        qualities.put("480p", 1500);
        qualities.put("360p", 800);
        AdaptiveBitrateSelector selector = new AdaptiveBitrateSelector(qualities);

        System.out.println("Viewer with 5000 kbps selects: " + selector.selectQuality(5000));
        System.out.println("Viewer with 7000 kbps selects: " + selector.selectQuality(7000));
        System.out.println("Viewer with 500 kbps (very poor connection) selects: " + selector.selectQuality(500));

        System.out.println("Same viewer, bandwidth drops to 1000 kbps, next segment selects: " + selector.selectQuality(1000));
    }
}

// Enforces a strict per-segment latency budget for live transcoding: a
// segment finishing within budget is distributed on time, one that misses
// it is dropped rather than allowed to delay the live stream further.
class LiveTranscodePipeline {
    private final long latencyBudgetMillis;

    LiveTranscodePipeline(long latencyBudgetMillis) {
        this.latencyBudgetMillis = latencyBudgetMillis;
    }

    String processSegment(String segmentId, long capturedAt, long transcodingCompletedAt) {
        long latency = transcodingCompletedAt - capturedAt;
        if (latency <= latencyBudgetMillis) {
            return "ON_TIME, latency=" + latency + "ms, distributed immediately";
        } else {
            return "DROPPED, latency=" + latency + "ms exceeds the " + latencyBudgetMillis + "ms budget";
        }
    }
}

// Selects the highest quality rendition whose bitrate still comfortably fits
// within a viewer's currently measured bandwidth, falling back to the lowest
// available quality if even that does not fit, rather than showing nothing at all.
class AdaptiveBitrateSelector {
    private final Map<String, Integer> qualityBitratesKbps; // quality label -> required bitrate

    AdaptiveBitrateSelector(Map<String, Integer> qualityBitratesKbps) {
        this.qualityBitratesKbps = qualityBitratesKbps;
    }

    String selectQuality(double measuredBandwidthKbps) {
        String best = null;
        int bestBitrate = -1;
        String lowestQuality = null;
        int lowestBitrate = Integer.MAX_VALUE;

        for (Map.Entry<String, Integer> entry : qualityBitratesKbps.entrySet()) {
            int bitrate = entry.getValue();
            if (bitrate < lowestBitrate) {
                lowestBitrate = bitrate;
                lowestQuality = entry.getKey(); // track the lowest quality as a fallback
            }
            if (bitrate <= measuredBandwidthKbps && bitrate > bestBitrate) {
                bestBitrate = bitrate;
                best = entry.getKey(); // the highest quality that still comfortably fits
            }
        }

        return (best != null) ? best : lowestQuality; // fall back to the lowest quality rather than nothing at all
    }
}

