// Enforces a strict per-segment latency budget for live transcoding: a
// segment finishing within budget is distributed on time, one that misses
// it is dropped rather than allowed to delay the live stream further.
class LiveTranscodePipeline {
public:
    LiveTranscodePipeline(long latencyBudgetMillis) : latencyBudgetMillis(latencyBudgetMillis) {}

    string processSegment(const string& segmentId, long capturedAt, long transcodingCompletedAt) {
        long latency = transcodingCompletedAt - capturedAt;
        if (latency <= latencyBudgetMillis) {
            return "ON_TIME, latency=" + to_string(latency) + "ms, distributed immediately";
        } else {
            return "DROPPED, latency=" + to_string(latency) + "ms exceeds the " + to_string(latencyBudgetMillis) + "ms budget";
        }
    }

private:
    long latencyBudgetMillis;
};

// Selects the highest quality rendition whose bitrate still comfortably fits
// within a viewer's currently measured bandwidth, falling back to the lowest
// available quality if even that does not fit, rather than showing nothing at all.
class AdaptiveBitrateSelector {
public:
    AdaptiveBitrateSelector(const map<string, int>& qualityBitratesKbps) : qualityBitratesKbps(qualityBitratesKbps) {}

    string selectQuality(double measuredBandwidthKbps) {
        string best = "";
        int bestBitrate = -1;
        string lowestQuality = "";
        int lowestBitrate = INT_MAX;

        for (const auto& entry : qualityBitratesKbps) {
            int bitrate = entry.second;
            if (bitrate < lowestBitrate) {
                lowestBitrate = bitrate;
                lowestQuality = entry.first; // track the lowest quality as a fallback
            }
            if (bitrate <= measuredBandwidthKbps && bitrate > bestBitrate) {
                bestBitrate = bitrate;
                best = entry.first; // the highest quality that still comfortably fits
            }
        }

        return !best.empty() ? best : lowestQuality; // fall back to the lowest quality rather than nothing at all
    }

private:
    map<string, int> qualityBitratesKbps; // quality label -> required bitrate
};

int main() {
    LiveTranscodePipeline pipeline(4000); // 4 second latency budget

    // Segment 1: captured at t=1000, finishes transcoding at t=3500 (2500ms latency): within budget.
    cout << "Segment 1: " << pipeline.processSegment("seg-1", 1000, 3500) << endl;

    // Segment 2: captured at t=1000, finishes transcoding at t=6000 (5000ms latency): exceeds budget.
    cout << "Segment 2: " << pipeline.processSegment("seg-2", 1000, 6000) << endl;

    // Adaptive bitrate selection. Using a map keeps qualities ordered by bitrate ascending.
    map<string, int> qualities = {{"360p", 800}, {"480p", 1500}, {"720p", 3000}, {"1080p", 6000}};
    AdaptiveBitrateSelector selector(qualities);

    cout << "Viewer with 5000 kbps selects: " << selector.selectQuality(5000) << endl;
    cout << "Viewer with 7000 kbps selects: " << selector.selectQuality(7000) << endl;
    cout << "Viewer with 500 kbps (very poor connection) selects: " << selector.selectQuality(500) << endl;

    cout << "Same viewer, bandwidth drops to 1000 kbps, next segment selects: " << selector.selectQuality(1000) << endl;

    return 0;
}

